// The site's Cloudflare Worker. /api requests are passed to the backend on Cloud Run with a secret
// header (the backend refuses anything without it), so every visitor, and every attack, goes through
// Cloudflare first. Everything else is the Next.js site, built by OpenNext.
// `.open-next/worker.js` is generated by `opennextjs-cloudflare build`.
import PostalMime from 'postal-mime';
import { default as site } from './.open-next/worker.js';

type Env = { API_ORIGIN: string; ORIGIN_SECRET: string; INBOUND_SECRET?: string; SUPPORT_FORWARD_TO?: string };
// The parts of Cloudflare's incoming email we use (Email Routing hands support@ mail to this Worker).
type IncomingEmail = { from: string; raw: ReadableStream; headers: Headers; forward: (to: string) => Promise<void> };
const HOME = 'readytowork.ph';

export default {
  async fetch(request: Request, env: Env, ctx: Parameters<typeof site.fetch>[2]) {
    const url = new URL(request.url);
    // One address for everyone: www and the old names (remoteworks.ph, remotepinas.com) move permanently to readytowork.ph,
    // keeping the page path, so old links and bookmarks still work.
    if (url.hostname !== HOME && url.hostname !== 'localhost') {
      return Response.redirect(`https://${HOME}${url.pathname}${url.search}`, 301);
    }
    if (!url.pathname.startsWith('/api/')) return site.fetch(request, env, ctx);

    const headers = new Headers(request.headers);
    headers.set('x-origin-secret', env.ORIGIN_SECRET);
    headers.set('x-visitor-ip', request.headers.get('cf-connecting-ip') ?? '');
    // Cloudflare's country for the visitor (Admin › Visitors); its cf-ipcountry header doesn't reach the backend.
    headers.set('x-visitor-country', (request as Request & { cf?: { country?: string } }).cf?.country ?? '');
    try {
      return await fetch(new URL(url.pathname + url.search, env.API_ORIGIN), {
        method: request.method,
        headers,
        body: request.body,
        redirect: 'manual', // photo links redirect to private storage; the browser follows them itself
      });
    } catch {
      // Backend unreachable: answer like the API would, so the site shows a friendly message.
      return Response.json({ error: 'ReadyToWork.ph is having trouble right now. Please try again in a minute.' }, { status: 503 });
    }
  },

  // Email to support@ (Cloudflare Email Routing → "Send to a Worker"). The original always goes on to the support
  // inbox (SUPPORT_FORWARD_TO); a copy goes to the admin panel, where replies to our answers join their ticket.
  // A failure here never loses the email: it has already been forwarded.
  async email(message: IncomingEmail, env: Env) {
    if (env.SUPPORT_FORWARD_TO) await message.forward(env.SUPPORT_FORWARD_TO);
    if (!env.INBOUND_SECRET) return;
    try {
      const mail = await PostalMime.parse(message.raw);
      const auto = (message.headers.get('auto-submitted') ?? 'no').toLowerCase() !== 'no'; // out-of-office replies and the like
      await fetch(new URL('/api/support/inbound', env.API_ORIGIN), {
        method: 'POST',
        headers: { 'content-type': 'application/json', 'x-origin-secret': env.ORIGIN_SECRET, 'x-inbound-secret': env.INBOUND_SECRET },
        body: JSON.stringify({
          from: mail.from?.address ?? message.from, from_name: mail.from?.name ?? '', subject: mail.subject ?? '',
          text: mail.text ?? (mail.html ?? '').replace(/<[^>]+>/g, ' '), message_id: mail.messageId ?? '', auto,
        }),
      });
    } catch (err) {
      console.error('Support email not added to the admin panel', err);
    }
  },
};
